\set ON_ERROR_STOP on
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SELECT json_build_object('kind','capture','data',json_build_object('captured_at',now(),'category_ids',ARRAY[5,9,13]));
SELECT json_build_object('kind','category','data',json_build_object('id',id,'name',name,'slug',slug,'color',color,'description',description,'topic_count',topic_count)) FROM categories WHERE id IN (5,9,13) AND NOT read_restricted ORDER BY id;
SELECT json_build_object('kind','topic','data',json_build_object('id',t.id,'title',t.title,'slug',t.slug,'created_at',t.created_at,'updated_at',t.updated_at,'last_posted_at',t.last_posted_at,'views',t.views,'posts_count',(SELECT count(*) FROM posts p WHERE p.topic_id=t.id AND p.deleted_at IS NULL AND NOT p.hidden AND NOT p.user_deleted AND p.post_type IN (1,2,3)),'user_id',t.user_id,'category_id',t.category_id,'like_count',t.like_count,'reply_count',t.reply_count,'highest_post_number',t.highest_post_number,'participant_count',t.participant_count,'word_count',t.word_count,'closed',t.closed,'archived',t.archived,'pinned_globally',t.pinned_globally,'tags',COALESCE((SELECT json_agg(tags.name) FROM topic_tags tt JOIN tags ON tags.id=tt.tag_id WHERE tt.topic_id=t.id),'[]'::json))) FROM topics t JOIN categories c ON c.id=t.category_id WHERE c.id IN (5,9,13) AND NOT c.read_restricted AND t.deleted_at IS NULL AND t.visible AND t.archetype='regular' ORDER BY t.id;
SELECT json_build_object('kind','post','data',json_build_object('id',p.id,'topic_id',p.topic_id,'post_number',p.post_number,'user_id',COALESCE(p.user_id,-1),'username',COALESCE(u.username,'deleted-user'),'name',u.name,'cooked',p.cooked,'created_at',p.created_at,'updated_at',p.updated_at,'reply_to_post_number',p.reply_to_post_number,'reply_count',p.reply_count,'reads',p.reads,'score',p.score,'like_count',p.like_count,'post_type',p.post_type,'avatar_upload_id',u.uploaded_avatar_id)) FROM posts p JOIN topics t ON t.id=p.topic_id JOIN categories c ON c.id=t.category_id LEFT JOIN users u ON u.id=p.user_id WHERE c.id IN (5,9,13) AND NOT c.read_restricted AND t.deleted_at IS NULL AND t.visible AND t.archetype='regular' AND p.deleted_at IS NULL AND NOT p.hidden AND NOT p.user_deleted AND p.post_type IN (1,2,3) ORDER BY p.topic_id,p.post_number;
WITH public_posts AS (SELECT p.id,p.user_id FROM posts p JOIN topics t ON t.id=p.topic_id JOIN categories c ON c.id=t.category_id WHERE c.id IN (5,9,13) AND NOT c.read_restricted AND t.deleted_at IS NULL AND t.visible AND t.archetype='regular' AND p.deleted_at IS NULL AND NOT p.hidden AND NOT p.user_deleted AND p.post_type IN (1,2,3)), upload_ids AS (SELECT DISTINCT r.upload_id FROM upload_references r JOIN public_posts p ON p.id=r.target_id WHERE r.target_type='Post' UNION SELECT DISTINCT u.uploaded_avatar_id FROM users u JOIN public_posts p ON p.user_id=u.id WHERE u.uploaded_avatar_id IS NOT NULL) SELECT json_build_object('kind','upload','data',json_build_object('id',u.id,'original_filename',u.original_filename,'filesize',u.filesize,'url',u.url,'sha1',u.sha1,'extension',u.extension,'width',u.width,'height',u.height)) FROM uploads u JOIN upload_ids i ON i.upload_id=u.id WHERE NOT u.secure ORDER BY u.id;
WITH public_posts AS (SELECT p.id FROM posts p JOIN topics t ON t.id=p.topic_id JOIN categories c ON c.id=t.category_id WHERE c.id IN (5,9,13) AND NOT c.read_restricted AND t.deleted_at IS NULL AND t.visible AND t.archetype='regular' AND p.deleted_at IS NULL AND NOT p.hidden AND NOT p.user_deleted AND p.post_type IN (1,2,3)), ids AS (SELECT DISTINCT r.upload_id FROM upload_references r JOIN public_posts p ON p.id=r.target_id WHERE r.target_type='Post') SELECT json_build_object('kind','optimized','data',json_build_object('upload_id',o.upload_id,'url',o.url)) FROM optimized_images o JOIN ids ON ids.upload_id=o.upload_id JOIN uploads u ON u.id=o.upload_id WHERE NOT u.secure;
ROLLBACK;
